// Leaflet is bundled so the map does not depend on a remote JavaScript CDN.
const fs = require("node:fs");
const path = require("node:path");
const root = path.dirname(require.resolve("leaflet/package.json"));
const js = fs
  .readFileSync(path.join(root, "dist/leaflet.js"), "utf8")
  .replace(/\/\/# sourceMappingURL=.*$/gm, "");
const css = fs.readFileSync(path.join(root, "dist/leaflet.css"), "utf8");
fs.writeFileSync(
  "src/ecoloop/maps/leaflet-vendor.ts",
  "// Generated by scripts/sync-map-vendor.cjs. Leaflet 1.9.4, BSD-2-Clause.\nexport const leafletScript = " +
    JSON.stringify(js) +
    ";\nexport const leafletCss = " +
    JSON.stringify(css) +
    ";\n",
);
fs.copyFileSync(
  path.join(root, "LICENSE"),
  "src/ecoloop/maps/LEAFLET-LICENSE.txt",
);
